/**
 * Browsable view of an arbitrary JSON value (`design/components/json-tree.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/json-tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  elementRef,
  jsonTreeBranches,
  jsonTreeExpanded,
  mountEffect,
  setJsonTreeBranch,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/json-tree.module.css'
import { JsonTreeEntry, type JsonTreeEntryProps } from './JsonTreeEntry'

/** Browsable view of an arbitrary JSON value: the inputs it takes, by the React member's prop names. */
export interface JsonTreeProps {
  /**
   * Any JSON value; `undefined` and other non-JSON values render as their `String()` form rather
   * than crashing a page that already has a bug.
   */
  data: unknown
  /**
   * Levels open at mount (`0` all closed, `Infinity` for payloads known to be small);
   * uncontrolled afterwards, because browsing is not app state.
   */
  defaultDepth?: number
  /**
   * The tree's accessible name, such as "Response body" rather than "JSON".
   */
  label: string
}

/** Browsable view of an arbitrary JSON value. */
@Component({
  selector: 'pm-json-tree',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, JsonTreeEntry],
  // prettier-ignore
  template: `<ul
[attr.class]="e1()"
[attr.aria-label]="e2()"
data-member="json-tree"
[pmRef]="tree"
><li
pmJsonTreeEntry
[value]="e3()"
[depth]="e4()"
[defaultDepth]="e5()"
></li></ul>`,
})
export class JsonTree {
  /**
   * Any JSON value; `undefined` and other non-JSON values render as their `String()` form rather
   * than crashing a page that already has a bug.
   */
  readonly data = input.required<JsonTreeProps['data']>()
  /**
   * Levels open at mount (`0` all closed, `Infinity` for payloads known to be small);
   * uncontrolled afterwards, because browsing is not app state.
   */
  readonly defaultDepth = input<
    Exclude<JsonTreeProps['defaultDepth'], undefined>,
    JsonTreeProps['defaultDepth']
  >(1, { transform: (value: JsonTreeProps['defaultDepth']) => (value === undefined ? 1 : value) })
  /**
   * The tree's accessible name, such as "Response body" rather than "JSON".
   */
  readonly label = input.required<JsonTreeProps['label']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      data: () => this.data(),
      defaultDepth: () => this.defaultDepth(),
      label: () => this.label(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly tree = elementRef<HTMLElement>()
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.label
  }

  protected e3(): JsonTreeEntryProps['value'] {
    return this.$p.data
  }

  protected e4(): JsonTreeEntryProps['depth'] {
    return 0
  }

  protected e5(): JsonTreeEntryProps['defaultDepth'] {
    return this.$p.defaultDepth
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'JsonTree',
      element: () => this.tree.value,
      state: () => ({
        expanded: jsonTreeExpanded(this.tree.value, styles.toggle, styles.key),
        branches: jsonTreeBranches(this.tree.value, styles.toggle, styles.key),
      }),
      actions: {
        expand: {
          argument: 'id',
          run: (value) =>
            setJsonTreeBranch(this.tree.value, styles.toggle, styles.key, value, true),
        },
        collapse: {
          argument: 'id',
          run: (value) =>
            setJsonTreeBranch(this.tree.value, styles.toggle, styles.key, value, false),
        },
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
